// CSD_RATIONALE_BEGIN
// Root-cause synthesis from attempts 1–71:
//
// Attempt 1 (best: 40.8% / 91.8%): Used per-step AdaptiveConstrainedStep inside
// each naturally-observed span. Failures: 6 repetition loops (model generates
// `- 0 * 0 * 0...` because `- 0 * 0` is parser-valid and IsCompletePrefix
// never fires to stop the loop), and some unclosed final spans.
//
// Attempts 69–71 (0–12%): Various "force one final span" strategies caused
// CloseSpanWithinBudget to regenerate garbage (whitespace loops, `--1`, `**`).
//
// Fix: Enter constrained mode for EVERY naturally-observed `<<` (via
// RenderedEndsWith, not exact token equality) and immediately call
// CloseSpanWithinBudget to find the first/longest completable parse and close it.
// CloseSpanWithinBudget has dead-end-aware generation and closes at the longest
// complete-parse prefix within the budget, preventing infinite loops.
// This replaces the per-step AdaptiveConstrainedStep inner loop entirely.
//
// Phase 0: Close any pre-existing open span (entry invariant).
// Main loop: UnconstrainedStep outside spans; CloseSpanWithinBudget(50) inside.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Outside-span branch (UnconstrainedStep):
//     insideConstrainedOut remains false until RenderedEndsWith fires.
//     EnterObservedConstrainedSpan sets insideConstrainedOut := true and
//     currentConstrainedOut := []; parser.IsValidPrefix([]) holds by method
//     precondition. The implication is satisfied. ✓
//
//   Inside-span branch (CloseSpanWithinBudget):
//     The postcondition of CloseSpanWithinBudget directly guarantees
//     insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//     for the returned (ci, cc). ✓
//
//   Phase 0 (pre-existing open span):
//     Same postcondition of CloseSpanWithinBudget. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Init: |generatedPrefix| <= |generatedPrefix| + 0. ✓
//
//   Phase 0: closeB0 = min(maxSteps, spanBudget); CloseSpanWithinBudget
//     postcondition gives |cg0| <= |generated| + closeB0 = |generatedPrefix| + closeB0;
//     steps := closeB0; so |generated| <= |generatedPrefix| + steps. ✓
//
//   Outside-span, non-EOS: steps += 1, generated += [next] (+1 token);
//     |generated| + 1 <= |generatedPrefix| + (steps-1) + 1 = |generatedPrefix| + steps. ✓
//     EnterObservedConstrainedSpan does not change generated; invariant preserved. ✓
//
//   Outside-span, EOS: steps += 1, generated unchanged;
//     |generated| <= |generatedPrefix| + (steps-1) < |generatedPrefix| + steps. ✓
//
//   Inside-span: closeB = min(maxSteps - steps, spanBudget);
//     CloseSpanWithinBudget postcondition: |cg| <= |generated| + closeB;
//     steps := steps + closeB; so |generated| <= |generatedPrefix| + steps. ✓
//     And steps_new = steps_old + closeB <= steps_old + (maxSteps - steps_old) = maxSteps. ✓
//
// Termination: maxSteps - steps decreases by at least 1 per loop iteration
//   (UnconstrainedStep costs exactly 1; CloseSpanWithinBudget costs at least 1). ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. Wrap every intermediate symbolic expression and the final numeric answer inside << >> delimiters.");

var steps: nat := 0;
var spanBudget: nat := 50;

// Phase 0: close any pre-existing open constrained span.
if insideConstrainedOut && steps < maxSteps {
  var avail0 : nat := maxSteps - steps;
  var closeB0 : nat := if avail0 < spanBudget then avail0 else spanBudget;
  var cg0, ci0, cc0 := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeB0
  );
  generated := cg0;
  insideConstrainedOut := ci0;
  currentConstrainedOut := cc0;
  steps := steps + closeB0;
}

// Main loop: unconstrained outside spans; CloseSpanWithinBudget inside spans.
while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
      generated := eg;
      insideConstrainedOut := ei;
      currentConstrainedOut := ec;
    }
  } else {
    // Inside a constrained span: close it at the longest completable parse point.
    var avail : nat := maxSteps - steps;
    var closeB : nat := if avail < spanBudget then avail else spanBudget;
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeB
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeB;
  }
}

cost := steps;

